INSERT INTO {schema}.axpflds
(tstruct, itype, fname, caption, "datatype", datawidth, flddecimal, modeofentry, "expression", valexpr, srctf, purpose, fldsql, srcfld, hidden, readonly, savevalue, dcname, ordno, customdatatype, stype, allowempty, allowduplicate, tabstop, setcarry, applycomma, onlypositive, clientvalidate, mask, pattern, hint, pwordchar, srckey, sgwidth, sgheight, cfield, srctrans, scol, autoselect, linkfield, suggestive, ctype, disptype, sep, font, color, refreshonsave, searchsql, dispdet, depflds, parentflds, listvalues, autogendet, tablename, asgrid, frmno, tlhw, lbltlhw, runtimefld, applyrule, createdby, createdon, modifiedby, modifiedon, "encrypted", masking, lastcharmask, firstcharmask, maskchar, maskroles, customdecimal, displaytotal)
VALUES('sect', 'Fields', 'menulist', 'Menu List', 'c', 500, 0, 'select', NULL, 'iif(isempty(menuposition)={F},menulist,{ Please select MenuList})', NULL, NULL, 'select cast(replace(replace(COALESCE(''\''||h.caption,'''')||COALESCE(''\''||g.caption,''''),''\\\'',''\''),''\\'',''\'') as varchar(500)) as menupath ,g.name as pageid
from axpages g
left join (select COALESCE(''\''||f.caption,'''')||COALESCE(''\''||e.caption,'''') as caption ,e.parent,e.name, COALESCE(f.levelno,3) as levelno
from axpages e
left join (select COALESCE(''\''||d.caption,'''')||''\''||COALESCE(c.caption,'''') as caption,c.name , COALESCE(d.levlno,2) as levelno
from axpages c
left join (select a.name,a.parent, a.caption ,a.levelno,cast(a.ordno as numeric) as ordno,1 as levlno
from axpages a 
 where levelno = 0
order by levelno,a.ordno) d  on (c.parent = d.name )
where c.levelno in (1,0) ) f on (e.parent = f.name)
where e.levelno in (1,0,2) ) h on (g.parent = h.name) 
where g.levelno <= 3 and ((g.name like ''Head%'' and COALESCE(h.levelno,4) in (4,3) and :menuposition = ''Add Under'') or :menuposition = ''Insert Before'' )
order by g.ordno,g.levelno
', NULL, 'T', 'F', 'T', 'dc1', 10, NULL, 's', 'T', 'T', 'T', 'F', 'T', 'T', 'T', NULL, NULL, NULL, NULL, 'F', '0', 0, NULL, NULL, 0, 'T', NULL, 'F', NULL, NULL, NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, NULL, NULL, 'htmlsections', 'F', 1, '126,163,18,250', '126,10,18,150', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

